        System.out.println("Action controls: "
          + actions.getComponentCount());
        System.out.println("Root groups: "
          + root.getComponentCount());
      }
    });
  }
}

public class Tricycle extends Vehicle {
    private String toda;

    public Tricycle(String plateNumber, String driverName, String toda) {
        super(plateNumber, driverName);
        this.toda = toda;
    }

    public String getToda() { return toda; }

    @Override
    public double computeFare(double km) {
        return 20.00 + (km * 10.00);
    }

    @Override
    public int getCapacity() { return 4; }
}

public abstract class Vehicle {
    private String plateNumber;
    private String driverName;
    private int passengers;

    public Vehicle(String plateNumber, String driverName) {
        this.plateNumber = plateNumber;
        this.driverName = driverName;
        this.passengers = 0;
    }

    public String getPlateNumber() { return plateNumber; }
    public String getDriverName()  { return driverName; }
    public int getPassengers()     { return passengers; }

    // WEDNESDAY: the setter now THROWS instead of only printing
    public void setPassengers(int passengers) {
        if (passengers < 0) {
            throw new IllegalArgumentException("Passengers cannot be negative: " + passengers);
        }
        this.passengers = passengers;
    }

    // THURSDAY: user-defined checked exception
    public void board(int count) throws OverloadException {
        if (passengers + count > getCapacity()) {
            throw new OverloadException(plateNumber + " is full! Capacity "
                + getCapacity() + ", but " + (passengers + count) + " tried to ride.");
        }
        passengers = passengers + count;
    }

    // THURSDAY: user-defined unchecked exception
    public double quoteFare(double km) {
        if (km <= 0) {
            throw new InvalidDistanceException("Distance must be more than 0 km, got " + km);
        }
        return computeFare(km);
    }

    public abstract double computeFare(double km);
    public abstract int getCapacity();

    public void showInfo() {
        System.out.println(plateNumber + " | Driver: " + driverName
            + " | Passengers: " + passengers + "/" + getCapacity());
    }
}

public class VehicleNotFoundException extends Exception {
    public VehicleNotFoundException(String message) {
        super(message);
    }
}

